WITH kept_keys AS (SELECT promo_code FROM promotions INTERSECT SELECT promo_code FROM promotions WHERE YEAR(ends_on) >= 2024), verified AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.promo_code = k.promo_code) SELECT id, promo_code, discount_pct, CASE WHEN promo_code RLIKE '^(BUNDLE|WELCOME5)$' THEN 'PRIORITY' WHEN promo_code RLIKE '^(SPRING10|VIP)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS promo_code_zone FROM verified ORDER BY promo_code;
